CREATE OR REPLACE FUNCTION public.audit_recurring_expense() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE schedule_uuid uuid; entry_uuid uuid; BEGIN IF TG_TABLE_NAME='recurring_expenses' THEN schedule_uuid:=NEW.id; ELSE schedule_uuid:=NEW.recurring_id; entry_uuid:=NEW.id; END IF; INSERT INTO public.recurring_expense_events(schedule_id,entry_id,actor_id,event,previous_values,new_values) VALUES(schedule_uuid,entry_uuid,auth.uid(),TG_TABLE_NAME||':'||lower(TG_OP),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;